

-- Model: sat_sk_kimbleone__timesheet__c_curr
-- Description: Current active record for TIMESHEET from SAT_SK_KIMBLEONE__TIMESHEET__C
-- Generated: 2025-05-19 21:48:09


WITH MAX_DATE AS (
    SELECT
        KIMBLEONE__TIMESHEET__C_HKEY,
        MAX(_AIRBYTE_EXTRACTED_AT) AS MAX_TRANS_DATE
    FROM {{ source('eli_dv_rv', 'sat_sk_kimbleone__timesheet__c') }}
    WHERE DELETE_FLAG = 'N'
    GROUP BY KIMBLEONE__TIMESHEET__C_HKEY
)

SELECT
    SAT_SRC.KIMBLEONE__TIMESHEET__C_HKEY,
    -- tagged: is_other_attr
    CREATEDBYID,
    CREATEDDATE,
    CURRENCYISOCODE,
    ISDELETED,
