    KIMBLEONE__APPROVER2USER6__C,
    KIMBLEONE__APPROVER2USER7__C,
    KIMBLEONE__APPROVER2USER8__C,
    KIMBLEONE__APPROVER2USER9__C,
    KIMBLEONE__APPROVER2USER__C,
    KIMBLEONE__INVOICINGCURRENCYISOCODE__C,
    KIMBLEONE__INVOICINGCURRENCYTOTALENTRYREVENUE__C,
    KIMBLEONE__OUTBOUNDINTERFACERUN__C,
    KIMBLEONE__RESOURCEDACTIVITY__C,
    KIMBLEONE__RESOURCEPERIOD__C,
    KIMBLEONE__RESOURCE__C,
    KIMBLEONE__STATUS__C,
    KIMBLEONE__TIMEADJUSTMENT__C,
    KIMBLEONE__TIMEPERIODSTARTDATE__C,
    KIMBLEONE__TIMEPERIOD__C,
    KIMBLEONE__TOTALENTRYREVENUE__C,
    KIMBLEONE__TOTALENTRYUNITS__C,
    KIMBLEONE__TOTALFACTOREDENTRYUNITS__C,
    KIMBLEONE__TOTALREVENUEUNITS__C,
    LASTMODIFIEDBYID,
    LASTMODIFIEDDATE,
    LASTREFERENCEDDATE,
    LASTVIEWEDDATE,
    NAME,
    OWNERID,
    SYSTEMMODSTAMP,
    _AIRBYTE_GENERATION_ID,
    _AIRBYTE_RAW_ID
FROM {{ source('eli_dv_rv', 'sat_sk_kimbleone__timesheet__c') }} SAT_SRC
INNER JOIN MAX_DATE MD
    ON SAT_SRC.KIMBLEONE__TIMESHEET__C_HKEY = MD.KIMBLEONE__TIMESHEET__C_HKEY
    AND SAT_SRC._AIRBYTE_EXTRACTED_AT = MD.MAX_TRANS_DATE
    AND SAT_SRC.DELETE_FLAG = 'N'



